mapper.select:
SELECT A.REGIST_BANK_CODE bankCode, A.PRODID prodId, A.INDENTIFY_MARK indentifyMark, B.PRODNAME prdName, A.CCY ccy, A.CCY ccyCode, A.AVAILABLE_QUANTITY availableQuantity, A.FROZEN_QUANTITY frozenQuantity, A.PLEDGED_QUANTITY pledgedQuantity, A.INIT_VAL_DATE initValDate, A.INIT_VAL_REGIST_DATE initValRegistDate, A.STATUS status, A.AMOUNT amount, A.CONVER_CNY_AMOUNT converCnyAmount, A.ORG_CODE orgCode FROM CHB_EQUPERIOD A LEFT JOIN CHB_PRDRESIST_CODE B ON A.PRODID = B.PRODID AND A.ORG_CODE = B.ORG_CODE
A.REGIST_BANK_CODE = #{bankCode,jdbcType=VARCHAR}
#{orgCode,jdbcType=VARCHAR}
#{prdCode,jdbcType=VARCHAR}
#{status,jdbcType=VARCHAR}
AND A.INDENTIFY_MARK = #{indentifyMark,jdbcType=VARCHAR}
#{key,jdbcType=VARCHAR}
ORDER BY A.UPDATE_TIME DESC,A.PRODID ASC

select count(*) from CHB_PRDRESIST_CODE
where PRODID = #{prodId,jdbcType=VARCHAR}

and ORG_CODE = #{orgCode,jdbcType=VARCHAR}
